  const d = s => { const m = String(s == null ? '' : s).match(/\d{4}-\d{2}-\d{2}/); return m ? m[0] : s; };
  const t = s => { const m = String(s == null ? '' : s).match(/\d{1,2}:\d{2}/); return m ? m[0] : s; };
