{ const _ds = res.occurrences.map(o => o.all_day ? o.date : String(o.start_iso).slice(0, 10)).sort();
  const _lim = new Date(_ds[0] + 'T00:00:00Z'); _lim.setUTCMonth(_lim.getUTCMonth() + 6);
  if (_ds[_ds.length - 1] > _lim.toISOString().slice(0, 10) || res.count > 200)
