const booked = [], skipped = [], notConf = [], failed = [];
for (let i = 0; i < occ.length; i++) {
  const r = results[i] || {}, date = occ[i]._date;
  if (r.status === 'CREATED') booked.push(date);
  else if (r.reason === 'ROOM_OCCUPIED' || r.status === 'ROOM_DECLINED') skipped.push(date);
  else if (r.reason === 'NOT_CONFIRMED') notConf.push(date);
  else failed.push({ date: date, why: (r.reason || r.status || 'unknown') });
}
if (notConf.length && notConf.length === occ.length) {
  return [{ json: { status: 'NOT_CONFIRMED',
    human: 'This series is not approved yet. Call Prepare Series with the same pattern and booking details and stop - its card is sent to the requester automatically, for their yes. Never write the dates or a summary yourself.' } }];
}
const line = d => '- ' + fmt(d) + ' (' + wd(d) + ')';
const parts = [];
if (booked.length) parts.push('Booked ' + booked.length + ' session' + (booked.length === 1 ? '' : 's') + ':\n' + booked.map(line).join('\n'));
if (skipped.length) parts.push('Skipped - the room was already taken on:\n' + skipped.map(line).join('\n') + '\nWant these at a different time, or a nearby day?');
if (failed.length) parts.push('Could not book:\n' + failed.map(f => line(f.date) + ' - ' + f.why).join('\n'));
const human = parts.join('\n\n') || 'Nothing was booked.';
const status = booked.length ? 'BOOKED_SERIES' : ((skipped.length || failed.length) ? 'NONE_BOOKED' : 'EMPTY');
return [{ json: { status: status, booked: booked, skipped: skipped, failed: failed, human: human } }];

// Series Out (Book Series v4): hands the prepared series back unchanged - Store Series only saved it. If the save failed the
// card still goes out; at the yes main finds nothing stored, so Series Direct does not run and the model is told the series
// is approved (Gate Context's seriesNotice) - never a booking with missing details.
return $('Aggregate').all().map(i => ({ json: Object.assign({}, i.json, { prep_stored: (function () { try { const s = $('Store Series').first().json || {}; return !s.error; } catch (e) { return false; } })() }) }));

// Span Input (v9, PENDING 150): one Room Availability call for every date of the series being prepared - the dates, the time,
// the booking's rooms (watched over each whole day, for the nearest free time), the same reference data Book Session gets.
const occ = $input.all().map(i => i.json || {});
const R = $('When Executed by Another Workflow').first().json || {};
const ds = occ.map(o => o._date).filter(Boolean);
const hm = iso => (String(iso || '').match(/T(\d{2}:\d{2})/) || [])[1] || '';
const allDay = !!(occ[0] || {}).all_day;
const t0 = allDay ? '00:00' : hm((occ[0] || {}).start_iso), t1 = allDay ? '23:59' : hm((occ[0] || {}).end_iso);
return [{ json: { dates: ds.join(','), t0, t1, start_iso: ds[0] + 'T' + t0 + ':00+08:00', end_iso: ds[ds.length - 1] + 'T' + t1 + ':00+08:00',
  session_type: String(R.session_type || ''), room: '', scope: '', hours: '', reference_data: String(R.reference_data || ''), watch: String(R.rooms || '') } }];

// First Date (v9, PENDING 150): Book Session's prepare checks run once - on the first date where every room of the booking is free
// (the details are the same on every date); with none free, the first date (Book Session then finds it another room or time).
const occ = $('Expand Dates').all().map(i => i.json || {}).filter(o => o._go);
const sp = $('Span Check').first().json || {};
const B = String(($('When Executed by Another Workflow').first().json || {}).rooms || '').split(',').map(s => s.trim()).filter(Boolean);
const day = {}; for (const x of [].concat(sp.per_date || [])) if (x && x.date) day[x.date] = x;
const freeOn = d => { const D = day[d]; if (!D || D.status !== 'OK') return false;
  const busy = new Set([].concat(D.busy || []).map(b => String(b).replace(/\s*\(.*$/, '').trim())); return B.every(r => !busy.has(r)); };
const pick = occ.find(o => freeOn(o._date)) || occ[0];
return pick ? [{ json: pick }] : [];
